package sprint

import (
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"strings"
	"time"

	"github.com/Antonio7098/ultraplan-go/internal/workspace"
)

const sprintWorkspaceSchemaVersion = 1

type SprintWorkspace struct {
	SchemaVersion int       `json:"schemaVersion"`
	SourceRoot    string    `json:"sourceRoot"`
	Path          string    `json:"path"`
	Branch        string    `json:"branch"`
	Baseline      string    `json:"baseline"`
	CreatedAt     time.Time `json:"createdAt"`
}

func sprintWorkspacePath(sp Sprint) string { return filepath.Join(sp.Path, ".workspace.json") }

func ResolveExecuteTarget(workspaceRoot, projectIndexContent string) (ExecuteTargetRef, []ValidationFinding) {
	target := extractTargetImplementationDirectory(projectIndexContent)
	if target == "" {
		return ExecuteTargetRef{}, []ValidationFinding{finding("Project Scope", "Target Implementation Directory", "", "missing target implementation directory", "project-index.md does not declare a target implementation directory", "Set Project Scope / Target Implementation Directory to the approved implementation repository.")}
	}
	clean := filepath.Clean(target)
	if !filepath.IsAbs(clean) {
		if strings.TrimSpace(workspaceRoot) == "" {
			return ExecuteTargetRef{}, []ValidationFinding{finding("Project Scope", "Target Implementation Directory", target, "relative target has no workspace root", "the target cannot be resolved without the UltraPlan workspace root", "Run the command from a valid UltraPlan workspace or use an absolute target path.")}
		}
		clean = filepath.Join(workspaceRoot, clean)
	}
	resolved, err := filepath.Abs(clean)
	if err != nil {
		return ExecuteTargetRef{}, []ValidationFinding{finding("Project Scope", "Target Implementation Directory", target, "target path cannot be resolved", err.Error(), "Use a valid absolute path or a path relative to the UltraPlan workspace root.")}
	}
	clean = filepath.Clean(resolved)
	info, err := os.Stat(clean)
	if err != nil {
		return ExecuteTargetRef{}, []ValidationFinding{finding("Project Scope", "Target Implementation Directory", target, "target root unavailable", err.Error(), "Create or restore the approved target repository before execute.")}
	}
	if !info.IsDir() {
		return ExecuteTargetRef{}, []ValidationFinding{finding("Project Scope", "Target Implementation Directory", target, "target root is not a directory", "path exists but is not a directory", "Use the approved target repository directory.")}
	}
	return ExecuteTargetRef{Path: clean, Source: "project-index.md"}, nil
}

func (s Service) resolveSprintTarget(sp Sprint, projectIndex string, create bool) (ExecuteTargetRef, []ValidationFinding) {
	if s.codeContextTarget != nil {
		return s.codeContextTarget(projectIndex)
	}
	source, findings := ResolveExecuteTarget(s.root, projectIndex)
	if len(findings) > 0 {
		return ExecuteTargetRef{}, findings
	}
	record, err := loadSprintWorkspace(sp)
	if err == nil {
		if validateErr := validateSprintWorkspace(record, source.Path); validateErr != nil {
			return ExecuteTargetRef{}, []ValidationFinding{finding("Sprint Workspace", "workspace", workspace.Rel(s.root, sprintWorkspacePath(sp)), "invalid sprint workspace", validateErr.Error(), "Restore the recorded worktree or explicitly recreate the sprint workspace.")}
		}
		return ExecuteTargetRef{Path: record.Path, Source: ".workspace.json"}, nil
	}
	if !os.IsNotExist(err) {
		return ExecuteTargetRef{}, []ValidationFinding{finding("Sprint Workspace", "workspace", workspace.Rel(s.root, sprintWorkspacePath(sp)), "unreadable sprint workspace", err.Error(), "Repair or remove the malformed sprint workspace record.")}
	}
	if !create {
		return source, nil
	}
	record, err = createSprintWorkspace(sp, source.Path, s.now().UTC())
	if err != nil {
		return ExecuteTargetRef{}, []ValidationFinding{finding("Sprint Workspace", "workspace", source.Path, "cannot create sprint workspace", err.Error(), "Commit or stash source changes, remove any conflicting branch or worktree, then retry.")}
	}
	return ExecuteTargetRef{Path: record.Path, Source: ".workspace.json"}, nil
}

func loadSprintWorkspace(sp Sprint) (SprintWorkspace, error) {
	data, err := os.ReadFile(sprintWorkspacePath(sp))
	if err != nil {
		return SprintWorkspace{}, err
	}
	var record SprintWorkspace
	if err := json.Unmarshal(data, &record); err != nil {
		return SprintWorkspace{}, fmt.Errorf("decode sprint workspace: %w", err)
	}
	if record.SchemaVersion != sprintWorkspaceSchemaVersion || record.SourceRoot == "" || record.Path == "" || record.Branch == "" || record.Baseline == "" {
		return SprintWorkspace{}, fmt.Errorf("invalid sprint workspace record")
	}
	return record, nil
}

func validateSprintWorkspace(record SprintWorkspace, source string) error {
	if filepath.Clean(record.SourceRoot) != filepath.Clean(source) {
		return fmt.Errorf("project target changed from %q to %q", record.SourceRoot, source)
	}
	info, err := os.Stat(record.Path)
	if err != nil {
		return fmt.Errorf("worktree unavailable: %w", err)
	}
	if !info.IsDir() {
		return fmt.Errorf("worktree path is not a directory")
	}
	sourceCommon, err := gitCommonDirectory(source)
	if err != nil {
		return fmt.Errorf("source Git metadata unavailable: %w", err)
	}
	workspaceCommon, err := gitCommonDirectory(record.Path)
	if err != nil || workspaceCommon != sourceCommon {
		return fmt.Errorf("worktree belongs to a different Git repository")
	}
	branch, err := gitOutput(record.Path, "branch", "--show-current")
	if err != nil || strings.TrimSpace(branch) != record.Branch {
		return fmt.Errorf("worktree is not on recorded branch %q", record.Branch)
	}
	return nil
}

func gitCommonDirectory(dir string) (string, error) {
	common, err := gitOutput(dir, "rev-parse", "--git-common-dir")
	if err != nil {
		return "", err
	}
	if !filepath.IsAbs(common) {
		common = filepath.Join(dir, common)
	}
	return filepath.Abs(filepath.Clean(common))
}

func createSprintWorkspace(sp Sprint, source string, now time.Time) (SprintWorkspace, error) {
	root, err := gitOutput(source, "rev-parse", "--show-toplevel")
	if err != nil {
		return SprintWorkspace{}, fmt.Errorf("target is not a Git worktree: %w", err)
	}
	root = filepath.Clean(root)
	if filepath.Clean(source) != root {
		return SprintWorkspace{}, fmt.Errorf("target must be the Git worktree root %q", root)
	}
	dirty, err := gitOutput(source, "status", "--porcelain", "--untracked-files=normal")
	if err != nil {
		return SprintWorkspace{}, fmt.Errorf("inspect target status: %w", err)
	}
	if strings.TrimSpace(dirty) != "" {
		return SprintWorkspace{}, fmt.Errorf("target has uncommitted changes")
	}
	baseline, err := gitOutput(source, "rev-parse", "HEAD")
	if err != nil {
		return SprintWorkspace{}, fmt.Errorf("resolve target HEAD: %w", err)
	}
	branch := "ultraplan/" + safeGitComponent(sp.Project) + "/" + safeGitComponent(sp.Slug)
	parent := filepath.Join(filepath.Dir(root), "."+filepath.Base(root)+"-ultraplan-worktrees")
	path := filepath.Join(parent, safeGitComponent(sp.Project), safeGitComponent(sp.Slug))
	if _, err := os.Lstat(path); !os.IsNotExist(err) {
		return SprintWorkspace{}, fmt.Errorf("worktree path already exists: %s", path)
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return SprintWorkspace{}, fmt.Errorf("create worktree parent: %w", err)
	}
	cmd := exec.Command("git", "-C", source, "worktree", "add", "-b", branch, path, strings.TrimSpace(baseline))
	if output, err := cmd.CombinedOutput(); err != nil {
		return SprintWorkspace{}, fmt.Errorf("git worktree add: %s: %w", strings.TrimSpace(string(output)), err)
	}
	record := SprintWorkspace{SchemaVersion: sprintWorkspaceSchemaVersion, SourceRoot: root, Path: path, Branch: branch, Baseline: strings.TrimSpace(baseline), CreatedAt: now}
	data, err := json.MarshalIndent(record, "", "  ")
	if err != nil {
		return SprintWorkspace{}, err
	}
	data = append(data, '\n')
	if err := atomicWriteFile(sprintWorkspacePath(sp), data); err != nil {
		_ = exec.Command("git", "-C", source, "worktree", "remove", path).Run()
		_ = exec.Command("git", "-C", source, "branch", "-D", branch).Run()
		return SprintWorkspace{}, fmt.Errorf("persist sprint workspace: %w", err)
	}
	return record, nil
}

func gitOutput(dir string, args ...string) (string, error) {
	cmd := exec.Command("git", append([]string{"-C", dir}, args...)...)
	output, err := cmd.CombinedOutput()
	if err != nil {
		return "", fmt.Errorf("%s: %w", strings.TrimSpace(string(output)), err)
	}
	return strings.TrimSpace(string(output)), nil
}

func safeGitComponent(value string) string {
	value = strings.ToLower(strings.TrimSpace(value))
	value = regexp.MustCompile(`[^a-z0-9._-]+`).ReplaceAllString(value, "-")
	value = strings.Trim(value, ".-")
	if value == "" {
		return "sprint"
	}
	return value
}

func ValidateExecuteWorkdir(target ExecuteTargetRef, workdir string) error {
	if target.Path == "" {
		return fmt.Errorf("missing execute target")
	}
	if workdir == "" {
		return fmt.Errorf("missing execute workdir")
	}
	targetPath := filepath.Clean(target.Path)
	workPath := filepath.Clean(workdir)
	if !filepath.IsAbs(workPath) {
		return fmt.Errorf("execute workdir %q must be absolute", workdir)
	}
	if !inside(targetPath, workPath) {
		return fmt.Errorf("execute workdir %q escapes approved target %q", workdir, target.Path)
	}
	return nil
}

func ExecuteSafetyInstructions(target ExecuteTargetRef) []string {
	return []string{
		"Work only inside approved target: " + target.Path,
		"Do not create smoke.md, smoke.json, generated review.md, issues.md, or issues.json.",
		"Do not run or request Git mutation: add, commit, push, branch, checkout, reset, PR creation, or issue tracking.",
		"Do not schedule cross-sprint work, launch a TUI, or build hosted/browser UI behavior.",
	}
}

func extractTargetImplementationDirectory(content string) string {
	re := regexp.MustCompile(`(?im)^\s*-\s+\*\*Target Implementation Directory:\*\*\s*(.+?)\s*$`)
	if match := re.FindStringSubmatch(content); len(match) == 2 {
		return strings.Trim(strings.TrimSpace(match[1]), "`")
	}
	re = regexp.MustCompile(`(?im)^\s*-\s+Target Implementation Directory:\s*(.+?)\s*$`)
	if match := re.FindStringSubmatch(content); len(match) == 2 {
		return strings.Trim(strings.TrimSpace(match[1]), "`")
	}
	return ""
}

package sprint

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"time"

	pruntime "github.com/Antonio7098/ultraplan-go/internal/platform/runtime"
	"github.com/Antonio7098/ultraplan-go/internal/project"
)

const (
	runtimeMetricsSchemaVersion = 1
	runtimeMetricsFileName      = ".runtime-metrics.json"
	maxRuntimeMetricRecords     = 512
)

type RuntimeTokenMetric struct {
	Known bool  `json:"known"`
	Value int64 `json:"value,omitempty"`
}

type SprintRuntimeMetric struct {
	Stage              PlanningStage      `json:"stage"`
	Operation          string             `json:"operation,omitempty"`
	Task               string             `json:"task,omitempty"`
	Coverage           string             `json:"coverage,omitempty"`
	RunID              string             `json:"run_id,omitempty"`
	SessionID          string             `json:"session_id,omitempty"`
	Status             string             `json:"status,omitempty"`
	Provider           string             `json:"provider,omitempty"`
	Model              string             `json:"model,omitempty"`
	PromptBytes        int                `json:"prompt_bytes"`
	SharedPrefixBytes  int                `json:"shared_prefix_bytes,omitempty"`
	StageSuffixBytes   int                `json:"stage_suffix_bytes"`
	SharedPrefixDigest string             `json:"shared_prefix_sha256,omitempty"`
	CacheKey           string             `json:"cache_key,omitempty"`
	InputTokens        RuntimeTokenMetric `json:"input_tokens"`
	OutputTokens       RuntimeTokenMetric `json:"output_tokens"`
	ReasoningTokens    RuntimeTokenMetric `json:"reasoning_tokens"`
	CacheReadTokens    RuntimeTokenMetric `json:"cache_read_tokens"`
	CacheWriteTokens   RuntimeTokenMetric `json:"cache_write_tokens"`
	TotalTokens        RuntimeTokenMetric `json:"total_tokens"`
	Turns              RuntimeTokenMetric `json:"turns"`
	CostAmount         float64            `json:"cost_amount,omitempty"`
	CostCurrency       string             `json:"cost_currency,omitempty"`
	CostEstimated      bool               `json:"cost_estimated,omitempty"`
	CostSource         string             `json:"cost_source,omitempty"`
	StartedAt          time.Time          `json:"started_at,omitempty"`
	FinishedAt         time.Time          `json:"finished_at,omitempty"`
	ErrorCategory      string             `json:"error_category,omitempty"`
}

type SprintRuntimeMetrics struct {
	SchemaVersion int                   `json:"schema_version"`
	Project       string                `json:"project"`
	Sprint        string                `json:"sprint"`
	UpdatedAt     time.Time             `json:"updated_at"`
	Runs          []SprintRuntimeMetric `json:"runs"`
}

func RuntimeMetricsRelPath(sp Sprint) string {
	return filepath.ToSlash(filepath.Join("projects", sp.Project, "sprints", sp.Slug, runtimeMetricsFileName))
}

func LoadRuntimeMetrics(root string, sp Sprint) (SprintRuntimeMetrics, error) {
	path, err := resolveSprintContained(root, sp, RuntimeMetricsRelPath(sp))
	if err != nil {
		return SprintRuntimeMetrics{}, err
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return SprintRuntimeMetrics{}, err
	}
	var metrics SprintRuntimeMetrics
	if err := json.Unmarshal(data, &metrics); err != nil {
		return SprintRuntimeMetrics{}, fmt.Errorf("decode sprint runtime metrics: %w", err)
	}
	if metrics.SchemaVersion != runtimeMetricsSchemaVersion || metrics.Project != sp.Project || metrics.Sprint != sp.Slug {
		return SprintRuntimeMetrics{}, fmt.Errorf("invalid sprint runtime metrics identity")
	}
	return metrics, nil
}

func (s Service) RuntimeMetrics(projectRef, sprintRef string) (SprintRuntimeMetrics, error) {
	projects, err := project.DiscoverProjects(s.root)
	if err != nil {
		return SprintRuntimeMetrics{}, err
	}
	p, err := project.ResolveProject(projects, projectRef)
	if err != nil {
		return SprintRuntimeMetrics{}, err
	}
	sprints, err := DiscoverSprints(s.root, p)
	if err != nil {
		return SprintRuntimeMetrics{}, err
	}
	sp, err := ResolveSprint(sprints, sprintRef)
	if err != nil {
		return SprintRuntimeMetrics{}, err
	}
	if !inside(p.Path, sp.Path) {
		return SprintRuntimeMetrics{}, fmt.Errorf("sprint path mismatch for %q", sp.Slug)
	}
	metrics, err := LoadRuntimeMetrics(s.root, sp)
	if errors.Is(err, os.ErrNotExist) {
		return SprintRuntimeMetrics{SchemaVersion: runtimeMetricsSchemaVersion, Project: sp.Project, Sprint: sp.Slug}, nil
	}
	return metrics, err
}

func (s Service) startSprintRuntime(ctx context.Context, sp Sprint, stage PlanningStage, req pruntime.Request) (pruntime.Result, error) {
	// Retry cleanup that was interrupted by a crash before admitting more work.
	// Recent failed stores remain available for session recovery.
	pruntime.CleanupRuntimeStores(sp.Path, 72*time.Hour, 2*1024*1024*1024, false)
	result, runErr := s.runtime.StartRun(ctx, req)
	if metricErr := s.recordRuntimeMetric(sp, stage, req, result); metricErr != nil {
		result.Warnings = append(result.Warnings, "runtime metrics were not persisted: "+safeError(metricErr))
	}
	return result, runErr
}

func (s Service) recordRuntimeMetric(sp Sprint, stage PlanningStage, req pruntime.Request, result pruntime.Result) error {
	if s.metricsMu != nil {
		s.metricsMu.Lock()
		defer s.metricsMu.Unlock()
	}
	metrics, err := LoadRuntimeMetrics(s.root, sp)
	if errors.Is(err, os.ErrNotExist) {
		metrics = SprintRuntimeMetrics{SchemaVersion: runtimeMetricsSchemaVersion, Project: sp.Project, Sprint: sp.Slug}
	} else if err != nil {
		return err
	}
	explanation := explainComposedPrompt(req.Prompt)
	record := SprintRuntimeMetric{
		Stage: stage, Operation: req.Metadata["operation"], Task: req.Metadata["task"], Coverage: req.Metadata["coverage"],
		RunID: result.RunID, SessionID: result.SessionID, Status: result.Status, Provider: req.Provider, Model: req.Model,
		PromptBytes: explanation.TotalBytes, SharedPrefixBytes: explanation.SharedPrefixBytes, StageSuffixBytes: explanation.StageSuffixBytes,
		SharedPrefixDigest: explanation.SharedPrefixDigest, CacheKey: explanation.CacheKey,
		InputTokens: metricToken(result.Usage.InputTokensKnown, result.Usage.InputTokens), OutputTokens: metricToken(result.Usage.OutputTokensKnown, result.Usage.OutputTokens),
		ReasoningTokens: metricToken(result.Usage.ReasoningTokensKnown, result.Usage.ReasoningTokens), CacheReadTokens: metricToken(result.Usage.CacheReadTokensKnown, result.Usage.CacheReadTokens),
		CacheWriteTokens: metricToken(result.Usage.CacheWriteTokensKnown, result.Usage.CacheWriteTokens), TotalTokens: metricToken(result.Usage.TotalTokensKnown, result.Usage.TotalTokens),
		Turns: metricToken(result.Usage.TurnsKnown, result.Usage.Turns), StartedAt: result.StartedAt, FinishedAt: result.FinishedAt,
	}
	if result.EstimatedCost != nil {
		record.CostAmount, record.CostCurrency, record.CostEstimated = result.EstimatedCost.Amount, result.EstimatedCost.Currency, result.EstimatedCost.Estimate
		record.CostSource = result.EstimatedCost.Source
	}
	if result.Error != nil {
		record.ErrorCategory = result.Error.Category
	}
	metrics.Runs = append(metrics.Runs, record)
	if len(metrics.Runs) > maxRuntimeMetricRecords {
		metrics.Runs = append([]SprintRuntimeMetric(nil), metrics.Runs[len(metrics.Runs)-maxRuntimeMetricRecords:]...)
	}
	metrics.UpdatedAt = s.now().UTC()
	data, err := json.MarshalIndent(metrics, "", "  ")
	if err != nil {
		return err
	}
	data = append(data, '\n')
	path, err := resolveSprintContained(s.root, sp, RuntimeMetricsRelPath(sp))
	if err != nil {
		return err
	}
	return atomicWriteFile(path, data)
}

func metricToken(known bool, value int64) RuntimeTokenMetric {
	return RuntimeTokenMetric{Known: known, Value: value}
}

package sprint

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/Antonio7098/ultraplan-go/internal/project"
	"github.com/Antonio7098/ultraplan-go/internal/workspace"
)

type ReasoningTemplateEntry struct {
	Name       string
	Template   string
	OutputPath string
	Why        string
}

type ReasoningManifest struct {
	ProjectSlug        string
	SprintSlug         string
	SprintRoot         string
	RequirementsPath   string
	SprintIndexPath    string
	HandbookPath       string
	FinalOutputPath    string
	Contracts          []SelectedItem
	EvidenceReports    []SelectedItem
	ReviewProtocols    []SelectedItem
	ExcludedContexts   []SelectedItem
	ReasoningTemplates []ReasoningTemplateEntry
}

func BuildReasoningManifest(root string, sp Sprint, inputs PlanningInputs, catalog project.ProjectIndex) (ReasoningManifest, []ValidationFinding) {
	index, findings := ValidateSprintIndexContent(inputs.SprintIndex, catalog)
	manifest := ReasoningManifest{
		ProjectSlug:      sp.Project,
		SprintSlug:       sp.Slug,
		SprintRoot:       filepath.ToSlash(filepath.Join("projects", sp.Project, "sprints", sp.Slug)),
		RequirementsPath: ArtifactRelPath(sp, StageRequirements),
		SprintIndexPath:  ArtifactRelPath(sp, StageSprintIndex),
		HandbookPath:     ArtifactRelPath(sp, StageTechnicalHandbook),
		FinalOutputPath:  ArtifactRelPath(sp, StageReasoning),
		Contracts:        append([]SelectedItem(nil), index.Contracts...),
		EvidenceReports:  append([]SelectedItem(nil), index.EvidenceReports...),
		ReviewProtocols:  append([]SelectedItem(nil), index.ReviewProtocols...),
		ExcludedContexts: append([]SelectedItem(nil), index.ExcludedContexts...),
	}
	for _, selected := range index.ReasoningTemplates {
		catalogEntry, ok := catalogReasoningTemplate(catalog, selected.Name)
		if !ok {
			continue
		}
		templateRel := normalizeWorkspacePath(catalogEntry.Path)
		if !safeWorkspaceRel(templateRel) {
			findings = append(findings, finding("Selected Reasoning Templates", selected.Name, catalogEntry.Path, "unsafe template path", "template path escapes the workspace", "Use a workspace-relative catalog path."))
			continue
		}
		full, err := workspace.ResolveInside(root, templateRel)
		if err != nil {
			findings = append(findings, finding("Selected Reasoning Templates", selected.Name, catalogEntry.Path, "unsafe template path", err.Error(), "Use a workspace-relative catalog path."))
			continue
		}
		info, err := os.Stat(full)
		if err != nil {
			findings = append(findings, finding("Selected Reasoning Templates", selected.Name, catalogEntry.Path, "unreadable selected template", err.Error(), "Ensure the selected reasoning template exists and is readable."))
			continue
		}
		if info.IsDir() || info.Size() == 0 {
			findings = append(findings, finding("Selected Reasoning Templates", selected.Name, catalogEntry.Path, "invalid selected template file", "path is empty or a directory", "Select a non-empty Markdown reasoning template."))
			continue
		}
		if !reasoningOutputInsideSprint(sp, selected.Path) {
			findings = append(findings, finding("Selected Reasoning Templates", selected.Name, selected.Path, "unsafe output path", "output path must be under the selected sprint reasoning directory", "Use projects/<project>/sprints/<sprint>/reasoning/<area>.md."))
			continue
		}
		manifest.ReasoningTemplates = append(manifest.ReasoningTemplates, ReasoningTemplateEntry{
			Name:       selected.Name,
			Template:   catalogEntry.Path,
			OutputPath: selected.Path,
			Why:        selected.Why,
		})
	}
	sort.SliceStable(manifest.ReasoningTemplates, func(i, j int) bool {
		if manifest.ReasoningTemplates[i].Name != manifest.ReasoningTemplates[j].Name {
			return manifest.ReasoningTemplates[i].Name < manifest.ReasoningTemplates[j].Name
		}
		return manifest.ReasoningTemplates[i].OutputPath < manifest.ReasoningTemplates[j].OutputPath
	})
	sortSprintFindings(findings)
	return manifest, findings
}

func ValidateAreaReasoningContent(content string, entry ReasoningTemplateEntry, manifest ReasoningManifest) []ValidationFinding {
	var findings []ValidationFinding
	if strings.TrimSpace(content) == "" {
		return []ValidationFinding{finding("area-reasoning", entry.Name, entry.OutputPath, "empty area reasoning", "file has no content", "Generate or write the required area reasoning sections.")}
	}
	if containsPlaceholder(content) {
		findings = append(findings, finding("area-reasoning", entry.Name, entry.OutputPath, "placeholder content", "file still contains placeholder markers", "Replace placeholders with concrete reasoning content."))
	}
	sections := markdownSections(content)
	for _, section := range []string{"Area Decisions", "Trade-Offs", "Evidence", "Risks"} {
		if strings.TrimSpace(sections[section]) == "" {
			findings = append(findings, finding(section, entry.Name, entry.OutputPath, "missing required section", "section was not found or has no content", "Add the required area reasoning section."))
		}
	}
	if !strings.Contains(content, entry.Name) && !strings.Contains(content, entry.Template) {
		findings = append(findings, finding("Evidence", entry.Name, entry.OutputPath, "missing selected template trace", "area reasoning does not name the selected template", "Reference the selected area/template being reasoned through."))
	}
	findings = append(findings, validateSelectedContextReferences(content, manifest)...)
	sortSprintFindings(findings)
	return findings
}

func ValidateFinalReasoningContent(content string, manifest ReasoningManifest) []ValidationFinding {
	var findings []ValidationFinding
	if strings.TrimSpace(content) == "" {
		return []ValidationFinding{finding("reasoning.md", "", manifest.FinalOutputPath, "empty final reasoning", "file has no content", "Generate or write the required final reasoning sections.")}
	}
	if containsPlaceholder(content) {
		findings = append(findings, finding("reasoning.md", "", manifest.FinalOutputPath, "placeholder content", "file still contains placeholder markers", "Replace placeholders with concrete reasoning content."))
	}
	sections := markdownSections(content)
	for _, section := range []string{"Decisions", "Expected Evidence", "Assumptions And Risks", "Implementation Constraints"} {
		if strings.TrimSpace(sections[section]) == "" {
			findings = append(findings, finding(section, "", manifest.FinalOutputPath, "missing required section", "section was not found or has no content", "Add the required final reasoning section."))
		}
	}
	for _, entry := range manifest.ReasoningTemplates {
		if !strings.Contains(content, entry.OutputPath) && !strings.Contains(content, entry.Name) {
			findings = append(findings, finding("Area-Specific Reasoning Inputs", entry.Name, entry.OutputPath, "missing selected area reference", "final reasoning does not reference a selected area reasoning artifact", "Reference each selected area reasoning output before completing final reasoning."))
		}
	}
	findings = append(findings, validateSelectedContextReferences(content, manifest)...)
	sortSprintFindings(findings)
	return findings
}

func validateSelectedContextReferences(content string, manifest ReasoningManifest) []ValidationFinding {
	allowed := map[string]bool{}
	for _, item := range manifest.Contracts {
		allowed[strings.ToLower(item.Name)] = true
		allowed[strings.ToLower(item.Path)] = true
		allowed[strings.ToLower(normalizeWorkspacePath(item.Path))] = true
	}
	for _, item := range manifest.EvidenceReports {
		allowed[strings.ToLower(item.Name)] = true
		allowed[strings.ToLower(item.Path)] = true
		allowed[strings.ToLower(normalizeWorkspacePath(item.Path))] = true
	}
	for _, item := range manifest.ReviewProtocols {
		allowed[strings.ToLower(item.Name)] = true
		allowed[strings.ToLower(item.Path)] = true
		allowed[strings.ToLower(normalizeWorkspacePath(item.Path))] = true
	}
	for _, entry := range manifest.ReasoningTemplates {
		allowed[strings.ToLower(entry.Name)] = true
		allowed[strings.ToLower(entry.Template)] = true
		allowed[strings.ToLower(normalizeWorkspacePath(entry.Template))] = true
		allowed[strings.ToLower(entry.OutputPath)] = true
		allowed[strings.ToLower(normalizeWorkspacePath(entry.OutputPath))] = true
	}
	allowed[strings.ToLower(manifest.RequirementsPath)] = true
	allowed[strings.ToLower(manifest.SprintIndexPath)] = true
	allowed[strings.ToLower(manifest.HandbookPath)] = true
	allowed[strings.ToLower(manifest.FinalOutputPath)] = true
	var findings []ValidationFinding
	for _, path := range selectedContextPaths(content) {
		lp := strings.ToLower(path)
		normalized := strings.ToLower(normalizeWorkspacePath(path))
		if allowed[lp] || allowed[normalized] {
			continue
		}
		findings = append(findings, finding("Selected Context", "", path, "unselected context reference", "reasoning cites a path not selected for this sprint", "Use only selected sprint-index context, handbook evidence, and selected area reasoning paths."))
	}
	return findings
}

func selectedContextPaths(content string) []string {
	matches := mdPathPattern.FindAllString(content, -1)
	for _, needle := range []string{".ultra/system/contracts/", ".ultra/system/protocols/", ".ultra/system/reasoning/"} {
		start := 0
		for {
			idx := strings.Index(content[start:], needle)
			if idx < 0 {
				break
			}
			idx += start
			end := idx
			for end < len(content) && !strings.ContainsRune(" \t\r\n`|,);", rune(content[end])) {
				end++
			}
			matches = append(matches, strings.Trim(content[idx:end], "`.,);"))
			start = end
		}
	}
	seen := map[string]bool{}
	var out []string
	for _, match := range matches {
		if match == "" || seen[match] {
			continue
		}
		seen[match] = true
		out = append(out, match)
	}
	sort.Strings(out)
	return out
}

func catalogReasoningTemplate(catalog project.ProjectIndex, name string) (project.CatalogEntry, bool) {
	for _, entry := range catalog.Entries {
		if entry.Section == project.SectionAvailableReasoningTemplate && strings.EqualFold(entry.Name, name) {
			return entry, true
		}
	}
	return project.CatalogEntry{}, false
}

func reasoningOutputInsideSprint(sp Sprint, output string) bool {
	if !safeWorkspaceRel(output) {
		return false
	}
	clean := filepath.ToSlash(filepath.Clean(filepath.FromSlash(normalizeWorkspacePath(output))))
	prefix := filepath.ToSlash(filepath.Join("projects", sp.Project, "sprints", sp.Slug, "reasoning")) + "/"
	return strings.HasPrefix(clean, prefix) && strings.ToLower(filepath.Ext(clean)) == ".md"
}

func safeWorkspaceRel(path string) bool {
	if path == "" || filepath.IsAbs(path) || strings.Contains(path, "\x00") {
		return false
	}
	clean := filepath.ToSlash(filepath.Clean(filepath.FromSlash(path)))
	return clean != "." && clean != ".." && !strings.HasPrefix(clean, "../")
}

func formatReasoningManifest(manifest ReasoningManifest) string {
	var b strings.Builder
	fmt.Fprintf(&b, "- Project: %s\n", manifest.ProjectSlug)
	fmt.Fprintf(&b, "- Sprint: %s\n", manifest.SprintSlug)
	fmt.Fprintf(&b, "- Sprint root: %s\n", manifest.SprintRoot)
	fmt.Fprintf(&b, "- Requirements: %s\n", manifest.RequirementsPath)
	fmt.Fprintf(&b, "- Sprint index: %s\n", manifest.SprintIndexPath)
	fmt.Fprintf(&b, "- Technical handbook: %s\n", manifest.HandbookPath)
	fmt.Fprintf(&b, "- Final reasoning output: %s\n", manifest.FinalOutputPath)
	fmt.Fprintln(&b, "- Selected contracts:")
	for _, item := range manifest.Contracts {
		fmt.Fprintf(&b, "  - %s\n", item.Name)
	}
	fmt.Fprintln(&b, "- Selected evidence:")
	for _, item := range manifest.EvidenceReports {
		fmt.Fprintf(&b, "  - %s: %s\n", item.Name, item.Path)
	}
	fmt.Fprintln(&b, "- Selected reasoning templates:")
	if len(manifest.ReasoningTemplates) == 0 {
		fmt.Fprintln(&b, "  - none")
	}
	for _, entry := range manifest.ReasoningTemplates {
		fmt.Fprintf(&b, "  - %s: template=%s output=%s\n", entry.Name, entry.Template, entry.OutputPath)
	}
	fmt.Fprintln(&b, "- Required review protocols:")
	for _, item := range manifest.ReviewProtocols {
		fmt.Fprintf(&b, "  - %s: %s\n", item.Name, item.Path)
	}
	return b.String()
}

package sprint

import (
	"context"
	"fmt"
	"strings"

	"github.com/Antonio7098/agentwrap"
	"github.com/Antonio7098/ultraplan-go/internal/project"
)

const generatedArtifactRepairAttempts = 1

func buildCodeContextRepairPrompt(path string, findings []ValidationFinding) string {
	var b strings.Builder
	fmt.Fprintf(&b, "Correct the previous response for UltraPlan artifact `%s`.\n", path)
	fmt.Fprintln(&b, "Return only one complete Markdown document beginning with `# Sprint Code Context`. Do not include a preamble or closing commentary, perform more tool calls, search for the workspace output path, or write any file. UltraPlan owns candidate persistence and promotion.")
	fmt.Fprintf(&b, "Keep the complete response at or below %d bytes. Store source references only; every selected entry needs Path, Lines, and Rationale, with no copied source or fenced code blocks.\n", maxCodeContextBytes)
	fmt.Fprintln(&b, "\nValidation findings:")
	if len(findings) == 0 {
		fmt.Fprintln(&b, "- The response did not satisfy the code-context contract; re-read the required template and return the complete corrected document.")
	} else {
		for _, finding := range findings {
			fmt.Fprintf(&b, "- %s\n", formatValidationFindings([]ValidationFinding{finding}))
		}
	}
	return b.String()
}

func (s Service) requirementsValidationSpec(sp Sprint) *agentwrap.ValidationSpec {
	return generatedArtifactValidationSpec("requirements", ArtifactRelPath(sp, StageRequirements), func() []ValidationFinding {
		data, err := s.store.ReadArtifact(sp, StageRequirements)
		if err != nil {
			return []ValidationFinding{finding("requirements.md", "", ArtifactRelPath(sp, StageRequirements), "missing requirements", err.Error(), "Generate requirements.md.")}
		}
		return ValidateRequirementsContent(data)
	})
}

func (s Service) sprintIndexValidationSpec(sp Sprint, catalog project.ProjectIndex) *agentwrap.ValidationSpec {
	return generatedArtifactValidationSpec("sprint-index", ArtifactRelPath(sp, StageSprintIndex), func() []ValidationFinding {
		inputs, err := s.store.ReadPlanningInputs(sp)
		if err != nil {
			return []ValidationFinding{finding("sprint-index.md", "", ArtifactRelPath(sp, StageSprintIndex), "missing sprint index", err.Error(), "Generate sprint-index.md.")}
		}
		_, findings := ValidateSprintIndexContent(inputs.SprintIndex, catalog)
		return findings
	})
}

func (s Service) technicalHandbookValidationSpec(sp Sprint, manifest HandbookManifest) *agentwrap.ValidationSpec {
	return generatedArtifactValidationSpec("technical-handbook", ArtifactRelPath(sp, StageTechnicalHandbook), func() []ValidationFinding {
		data, err := s.store.ReadArtifact(sp, StageTechnicalHandbook)
		if err != nil {
			return []ValidationFinding{finding("technical-handbook.md", "", ArtifactRelPath(sp, StageTechnicalHandbook), "missing technical handbook", err.Error(), "Generate technical-handbook.md.")}
		}
		return ValidateTechnicalHandbookContent(data, manifest)
	})
}

func (s Service) areaReasoningEntryValidationSpec(manifest ReasoningManifest, entry ReasoningTemplateEntry) *agentwrap.ValidationSpec {
	return generatedArtifactValidationSpec("area-reasoning-"+slugReviewID(entry.Name), entry.OutputPath, func() []ValidationFinding {
		return s.areaReasoningEntryFindings(manifest, entry)
	})
}

func (s Service) finalReasoningValidationSpec(sp Sprint, manifest ReasoningManifest) *agentwrap.ValidationSpec {
	return generatedArtifactValidationSpec("reasoning", ArtifactRelPath(sp, StageReasoning), func() []ValidationFinding {
		data, err := s.store.ReadArtifact(sp, StageReasoning)
		if err != nil {
			return []ValidationFinding{finding("reasoning.md", "", ArtifactRelPath(sp, StageReasoning), "missing final reasoning", err.Error(), "Generate reasoning.md.")}
		}
		return ValidateFinalReasoningContent(data, manifest)
	})
}

func (s Service) planValidationSpec(sp Sprint, manifest PlanManifest) *agentwrap.ValidationSpec {
	return generatedArtifactValidationSpec("plan", ArtifactRelPath(sp, StagePlan), func() []ValidationFinding {
		data, err := s.store.ReadArtifact(sp, StagePlan)
		if err != nil {
			return []ValidationFinding{finding("plan.md", "", ArtifactRelPath(sp, StagePlan), "missing plan", err.Error(), "Generate plan.md.")}
		}
		return ValidatePlanContent(data, manifest)
	})
}

func generatedArtifactValidationSpec(id, path string, validate func() []ValidationFinding) *agentwrap.ValidationSpec {
	return &agentwrap.ValidationSpec{
		Validators: []agentwrap.Validator{agentwrap.ValidatorFunc(func(ctx context.Context, _ agentwrap.ValidationContext) agentwrap.ValidationCheck {
			select {
			case <-ctx.Done():
				return agentwrap.ValidationCheck{
					ExpectationID: id,
					Kind:          agentwrap.ExpectationCustom,
					Severity:      agentwrap.ExpectationRequired,
					Passed:        false,
					Expected:      "valid generated artifact",
					Observed:      ctx.Err().Error(),
					Detail:        "validation cancelled",
					RepairHint:    "Retry generation when the context is active.",
				}
			default:
			}
			findings := validate()
			if len(findings) == 0 {
				return agentwrap.ValidationCheck{
					ExpectationID: id,
					Kind:          agentwrap.ExpectationCustom,
					Severity:      agentwrap.ExpectationRequired,
					Passed:        true,
					Expected:      "valid generated artifact",
					Observed:      "valid",
					Detail:        path + " passed UltraPlan validation",
				}
			}
			return agentwrap.ValidationCheck{
				ExpectationID: id,
				Kind:          agentwrap.ExpectationCustom,
				Severity:      agentwrap.ExpectationRequired,
				Passed:        false,
				Expected:      "valid generated artifact",
				Observed:      formatValidationFindings(findings),
				Detail:        path + " failed UltraPlan validation",
				RepairHint:    "Update only " + path + " so it satisfies the listed UltraPlan validation findings.",
			}
		})},
		Repair: agentwrap.RepairConfig{
			MaxAttempts:                 generatedArtifactRepairAttempts + 1,
			SessionAction:               agentwrap.SessionActionContinue,
			AllowFreshSessionFallback:   true,
			FreshSessionFallbackOnError: true,
			BuildPrompt: func(ctx agentwrap.RepairContext) string {
				return buildGeneratedArtifactRepairPrompt(path, ctx.Validation.Failures)
			},
			OverrideRequest: func(ctx agentwrap.RepairContext, req agentwrap.RunRequest) agentwrap.RunRequest {
				if ctx.Attempt >= 2 {
					req.SessionID = ""
					req.SessionAction = agentwrap.SessionActionFresh
				}
				return req
			},
		},
	}
}

func buildGeneratedArtifactRepairPrompt(path string, failures []agentwrap.ValidationFailure) string {
	var b strings.Builder
	fmt.Fprintf(&b, "Repair the generated UltraPlan artifact `%s` so validation passes.\n\n", path)
	fmt.Fprintln(&b, "Use the same sprint context and previous work. Update only the artifact named above unless a listed validation finding explicitly requires another selected output.")
	fmt.Fprintln(&b, "\nValidation findings:")
	if len(failures) == 0 {
		fmt.Fprintln(&b, "- validation failed, but no detailed findings were provided; inspect the artifact and satisfy the required template sections.")
	} else {
		for _, failure := range failures {
			fmt.Fprintf(&b, "- %s: %s\n", failure.ExpectationID, strings.TrimSpace(failure.Observed))
			if strings.TrimSpace(failure.RepairHint) != "" {
				fmt.Fprintf(&b, "  Fix: %s\n", strings.TrimSpace(failure.RepairHint))
			}
		}
	}
	fmt.Fprintln(&b, "\nAfter editing, stop. Do not modify source repositories, Git state, workspace config, or unrelated sprint artifacts.")
	return b.String()
}

func buildGeneratedArtifactRepairPromptFromFindings(path string, findings []ValidationFinding) string {
	failures := make([]agentwrap.ValidationFailure, 0, len(findings))
	for _, finding := range findings {
		failures = append(failures, agentwrap.ValidationFailure{
			ExpectationID: finding.Section,
			Kind:          agentwrap.ExpectationCustom,
			Severity:      agentwrap.ExpectationRequired,
			Expected:      "valid generated artifact",
			Observed:      formatValidationFindings([]ValidationFinding{finding}),
			Detail:        finding.Problem,
			RepairHint:    finding.Suggestion,
		})
	}
	return buildGeneratedArtifactRepairPrompt(path, failures)
}

func formatValidationFindings(findings []ValidationFinding) string {
	var b strings.Builder
	for i, finding := range findings {
		if i > 0 {
			b.WriteString("\n")
		}
		fmt.Fprintf(&b, "%s", finding.Section)
		if finding.EntryName != "" {
			fmt.Fprintf(&b, " %q", finding.EntryName)
		}
		if finding.Path != "" {
			fmt.Fprintf(&b, " (%s)", finding.Path)
		}
		if finding.Problem != "" {
			fmt.Fprintf(&b, ": %s", finding.Problem)
		}
		if finding.Cause != "" {
			fmt.Fprintf(&b, "; %s", finding.Cause)
		}
		if finding.Suggestion != "" {
			fmt.Fprintf(&b, "; fix: %s", finding.Suggestion)
		}
	}
	return b.String()
}

